def longest_border_length(s):
    n = len(s)
    if n == 0:
        return 0
    fail = [0] * n
    for i in range(1, n):
        j = fail[i - 1]
        while j > 0 and s[i] != s[j]:
            j = fail[j - 1]
        if s[i] == s[j]:
            j += 1
        fail[i] = j
    return fail[-1]

def sort_by_char_sum(words):
    def csum(w):
        return sum(ord(c) for c in w)
    return sorted(words, key=lambda w: (csum(w), w))

def count_pairs(pairs):
    d = {}
    for p in pairs:
        t = tuple(p)
        d[t] = d.get(t, 0) + 1
