def split_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def format_ordinal_date(day, month_name):
    a = abs(day)
    if 11 <= a % 100 <= 13:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(a % 10, 'th')
    return f"{day}{suf} of {month_name}"

def trim_matching_ends(s, ch):
    i, j = 0, len(s)
    while i < j and s[i] == ch:
        i += 1
    while j > i and s[j - 1] == ch:
        j -= 1
    return s[i:j]

def min_adjacent_swaps_to_sort(arr):
