def most_common_pair(pairs):
    counts = {}
    for p in pairs:
        counts[p] = counts.get(p, 0) + 1
    best = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[0]
    return best[0]

def is_repeated_pattern(s):
    n = len(s)
    if n == 0:
        return False
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return True
    return False

def group_by_first_letter(words):
    d = {}
    for w in words:
        if w:
            d.setdefault(w[0], []).append(w)
    return {k: sorted(v) for k, v in d.items()}

def count_words_case_insensitive(text):
    d = {}
    for w in text.split():
        lw = w.lower()
        d[lw] = d.get(lw, 0) + 1
    return d

def is_valid_us_phone_number(s):
    if len(s) != 14:
        return False
    if s[0] != '(' or s[4] != ')' or s[5] != ' ' or s[9] != '-':
        return False
    area, mid, last = s[1:4], s[6:9], s[10:14]
    if not (area.isdigit() and mid.isdigit() and last.isdigit()):
        return False
    return area[0] in '23456789'

def least_common_element(seq):
    if not seq:
        return None
    counts = {}
    for x in seq:
        counts[x] = counts.get(x, 0) + 1
    best = sorted(counts.items(), key=lambda kv: (kv[1], kv[0]))[0]
    return best[0]

def count_divisor_pairs(n):
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
        i += 1
    return count

def count_repeating_unit_repeats(s):
    n = len(s)
    if n == 0:
        return 0
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return n // length
    return 1

def merge_min_all_keys(a, b):
    result = dict(a)
    for k, v in b.items():
        if k in result:
            result[k] = min(result[k], v)
        else:
            result[k] = v
    return result

def is_valid_spaced_credit_card(s):
    import re
    if not re.fullmatch(r'\d{4} \d{4} \d{4} \d{4}', s):
        return False
    digits = s.replace(' ', '')
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def sum_of_divisors(n):
    n = abs(n)
    if n == 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            if i * i != n:
                total += n // i
        i += 1
    return total

def is_valid_python_identifier(s):
    keywords = {'if', 'else', 'elif', 'for', 'while', 'def', 'return', 'class', 'import', 'in',
                'not', 'and', 'or', 'True', 'False', 'None', 'break', 'continue', 'pass', 'try',
                'except', 'finally', 'with', 'as', 'lambda', 'yield'}
    if not s:
        return False
    if not (s[0].isalpha() or s[0] == '_'):
        return False
    if not all(c.isalnum() or c == '_' for c in s):
        return False
    return s not in keywords

def is_valid_weighted_checksum_ascending_mod11(s):
    if len(s) < 2:
        return False
    body, check = s[:-1], s[-1]
    if not body.isdigit():
        return False
    total = sum((i + 1) * int(d) for i, d in enumerate(body))
    rem = total % 11
    expected = 'X' if rem == 10 else str(rem)
    return check == expected

def dense_rank(nums):
    uniq = sorted(set(nums))
    rank_map = {v: i + 1 for i, v in enumerate(uniq)}
    return [rank_map[x] for x in nums]
